    "base_speed": 1.4,
    "kp": 3.0,
    "ki": 0.0,
    "kd": 0.3,
    "sensor_weights": [-1.0, -0.5, 0.0, 0.5, 1.0],
    "line_loss": "last_direction"
  },
  "observation_request": {
    "measurements": [
      "completion",
      "progress",
      "completion_time",
